    const value: I32 = this; // error
    takeI32(this); // error
    this satisfies I32; // error
    const arrow = (): I32 => this; // error
    return this; // error
  }
}

function testParameter2<T extends Type>(o: T): I32 | undefined {
  if (o.group === "scalar") {
    const value: I32 = o; // ok
